//! Cross-library validation gates for sci-form's Extended Hückel Theory
//! (ficha F86-EHT) and for its EEQ2019 charge model (ficha F87-EEQ2019).
//!
//! Both gates consume the fixtures generated by the oracles in
//! `scripts/validation/` and recompute the sci-form side, so CI validates
//! real cross-implementation agreement without any external dependency.
//!
//! | ficha     | what is compared                                            |
//! |-----------|-------------------------------------------------------------|
//! | F86-EHT   | EHT overlap S, Wolfsberg-Helmholtz H, orbital energies,      |
//! |           | HOMO/LUMO/gap and the derived (hydrogenic) metal parameters   |
//! | F87-EEQ2019 | EEQ2019 partial charges and the total-charge constraint    |
//!
//! The EHT oracle (`scripts/validation/oracle_eht.py`) re-implements
//! Extended Hückel Theory independently in numpy: the STO-nG expansion
//! (HSP 1969 / Stewart 1970 contraction tables, transcribed in the oracle
//! and cross-checked against `src/eht/basis.rs`), the analytic Gaussian
//! overlap, the Wolfsberg-Helmholtz Hamiltonian and the generalized
//! eigenproblem.  Its overlap integrals were additionally validated
//! against libcint (PySCF) to <= 4.6e-8 for the same contractions.
//!
//! The EEQ2019 oracle (`scripts/validation/oracle_eeq2019.py`) re-implements
//! the published EEQ2019 model (Grimme et al., JCTC 2019) in numpy from the
//! equations: erf-type coordination numbers with a log cut at CN_max = 8,
//! Gaussian-width Coulomb kernel A_ij = erf(r gamma)/r with
//! gamma^2 = 1/(rad_i^2 + rad_j^2), A_ii = eta + sqrt(2/pi)/rad and the
//! CN-dependent electronegativity
//! chi_i = -chi_i^0 + k_cnchi CN_i / sqrt(CN_i).
//!
//! Regenerate the fixtures with:
//! ```bash
//! python scripts/validation/oracle_eht.py
//! python scripts/validation/oracle_eeq2019.py
//! ```

use std::path::PathBuf;

use serde::Deserialize;

fn fixture_path(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("validation")
        .join(name)
}

fn load<T: for<'de> Deserialize<'de>>(name: &str) -> T {
    let path = fixture_path(name);
    let data = std::fs::read_to_string(&path).unwrap_or_else(|err| {
        panic!(
            "missing fixture {} ({err}); run `scripts/run_validation.sh` (or the matching oracle)",
            path.display()
        )
    });
    serde_json::from_str(&data).expect("invalid fixture JSON")
}

/// Write the measured metric to `target/validation/{ficha}.json` so
/// `scripts/validation/collect.py` can merge it into the human-readable
/// `reports/validation/summary.json` after the test run.
fn record(
    ficha: &str,
    observable: &str,
    metric: &str,
    value: f64,
    tolerance: f64,
    passed: bool,
    n_cases: usize,
) {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("target")
        .join("validation");
    let _ = std::fs::create_dir_all(&dir);
    let payload = serde_json::json!({
        "ficha": ficha,
        "observable": observable,
        "metric": metric,
        "value": value,
        "tolerance": tolerance,
        "pass": passed,
        "n_cases": n_cases,
        "source": "tests/eht_eeq_parity.rs",
    });
    let path = dir.join(format!("{ficha}.json"));
    let mut rows: Vec<serde_json::Value> = std::fs::read_to_string(&path)
        .ok()
        .and_then(|text| serde_json::from_str::<serde_json::Value>(&text).ok())
        .map(|value| match value {
            serde_json::Value::Array(items) => items,
            other => vec![other],
        })
        .unwrap_or_default();
    rows.retain(|row| row.get("observable").and_then(|v| v.as_str()) != Some(observable));
    rows.push(payload);
    let _ = std::fs::write(&path, serde_json::Value::Array(rows).to_string());
}

// ═══════════════════════════════════════════════════════════════════════════
// F86-EHT — Extended Hückel Theory vs an independent numpy implementation
// ═══════════════════════════════════════════════════════════════════════════

mod f86_eht {
    use super::*;
    use sci_form::eht::basis::build_basis;
    use sci_form::eht::hamiltonian::build_hamiltonian;
    use sci_form::eht::metal_fallback::derived_params;
    use sci_form::eht::overlap::build_overlap_matrix;
    use sci_form::eht::solver::solve_eht;

    #[derive(Deserialize)]
    struct Case {
        name: String,
        elements: Vec<u8>,
        coords: Vec<f64>,
        n_basis: usize,
        ao_labels: Vec<String>,
        n_electrons: usize,
        /// Overlap matrix with the Extended-Hückel convention S_ii = 1.
        overlap: Vec<Vec<f64>>,
        /// Integral of the *unnormalised* STO-nG contraction over itself.
        overlap_true_diagonal: Vec<f64>,
        /// Wolfsberg-Helmholtz Hamiltonian (eV).
        hamiltonian: Vec<Vec<f64>>,
        energies_ev: Vec<f64>,
        /// Same eigenvalues with the computed (not normalised) S diagonal.
        energies_ev_true_diagonal: Vec<f64>,
        homo_index: usize,
        lumo_index: usize,
        homo_ev: f64,
        lumo_ev: f64,
        gap_ev: f64,
    }

    #[derive(Deserialize)]
    struct DerivedOrbital {
        n: u8,
        l: u8,
        label: String,
        vsip: f64,
        zeta: f64,
    }

    #[derive(Deserialize)]
    struct DerivedCase {
        z: u8,
        orbitals: Vec<DerivedOrbital>,
    }

    #[derive(Deserialize)]
    struct Sto3gTable {
        #[allow(dead_code)]
        rust: Vec<Vec<f64>>,
        #[allow(dead_code)]
        oracle: Vec<Vec<f64>>,
        max_abs_diff: f64,
        identical: bool,
    }

    #[derive(Deserialize)]
    struct Fixture {
        cases: Vec<Case>,
        derived_params: Vec<DerivedCase>,
        sto3g_tables_identical_to_rust: bool,
        sto3g_tables: std::collections::BTreeMap<String, Sto3gTable>,
    }

    /// Tolerances (measured 2026-10-21).
    ///
    /// * `OVERLAP_TOL` — the analytic Gaussian overlap; the oracle uses a
    ///   different but equivalent route (moment expansion) and the Rust uses
    ///   the Obara-Saika recursion, so only round-off separates them.
    /// * `H_TOL` — the Wolfsberg-Helmholtz Hamiltonian (eV).
    /// * `ENERGY_TOL` — the orbital energies (eV); the Rust uses Löwdin
    ///   orthogonalisation plus an iterative eigen-solver, the oracle uses
    ///   scipy's symmetric generalized solver.
    const OVERLAP_TOL: f64 = 1e-10;
    const H_TOL: f64 = 1e-10;
    const ENERGY_TOL: f64 = 1e-6;
    const PARAM_TOL: f64 = 1e-12;

    fn max_abs_diff(a: &[f64], b: &[f64]) -> f64 {
        let n = a.len().min(b.len());
        let mut worst = 0.0f64;
        for i in 0..n {
            worst = worst.max((a[i] - b[i]).abs());
        }
        worst
    }

    #[test]
    fn f86_eht_matches_independent_oracle() {
        let fixture: Fixture = load("eht_parity.json");
        assert!(fixture.cases.len() >= 8, "expected at least 8 EHT cases");

        // The STO-nG contraction tables must be the published ones on both
        // sides; a divergence here invalidates every energy comparison.
        assert!(
            fixture.sto3g_tables_identical_to_rust,
            "the oracle's STO-nG tables differ from sci-form's src/eht/basis.rs: {:?}",
            fixture
                .sto3g_tables
                .iter()
                .filter(|(_, v)| !v.identical)
                .map(|(k, v)| (k, v.max_abs_diff))
                .collect::<Vec<_>>()
        );
        for (name, table) in &fixture.sto3g_tables {
            assert!(
                table.max_abs_diff <= 1e-12,
                "STO-nG table {name} differs by {}",
                table.max_abs_diff
            );
        }

        let mut worst_overlap = (0.0f64, String::new());
        let mut worst_h = (0.0f64, String::new());
        let mut worst_energy = (0.0f64, String::new());
        let mut worst_homo = (0.0f64, String::new());
        let mut worst_lumo = (0.0f64, String::new());
        let mut worst_gap = (0.0f64, String::new());
        let mut worst_diag = (0.0f64, String::new());
        let mut worst_diag_effect = (0.0f64, String::new());

        for case in &fixture.cases {
            let positions: Vec<[f64; 3]> = case
                .coords
                .chunks_exact(3)
                .map(|c| [c[0], c[1], c[2]])
                .collect();
            assert_eq!(
                positions.len(),
                case.elements.len(),
                "{}: atom count",
                case.name
            );

            let basis = build_basis(&case.elements, &positions);
            assert_eq!(
                basis.len(),
                case.n_basis,
                "{}: basis function count {} != {}",
                case.name,
                basis.len(),
                case.n_basis
            );
            let labels: Vec<String> = basis.iter().map(|ao| ao.label.clone()).collect();
            assert_eq!(labels, case.ao_labels, "{}: AO ordering", case.name);

            let s = build_overlap_matrix(&basis);
            let h = build_hamiltonian(&basis, &s, None);
            assert_eq!(s.nrows(), case.n_basis);
            assert_eq!(h.nrows(), case.n_basis);

            // --- overlap matrix ---------------------------------------------
            let mut s_dev = 0.0f64;
            for i in 0..case.n_basis {
                for j in 0..case.n_basis {
                    s_dev = s_dev.max((s[(i, j)] - case.overlap[i][j]).abs());
                }
            }
            if s_dev > worst_overlap.0 {
                worst_overlap = (s_dev, case.name.clone());
            }

            // --- Hamiltonian ------------------------------------------------
            let mut h_dev = 0.0f64;
            for i in 0..case.n_basis {
                for j in 0..case.n_basis {
                    h_dev = h_dev.max((h[(i, j)] - case.hamiltonian[i][j]).abs());
                }
            }
            if h_dev > worst_h.0 {
                worst_h = (h_dev, case.name.clone());
            }

            // --- full EHT calculation ---------------------------------------
            let result = solve_eht(&case.elements, &positions, None)
                .unwrap_or_else(|err| panic!("{}: EHT failed: {err}", case.name));
            assert_eq!(
                result.n_electrons, case.n_electrons,
                "{}: valence electron count",
                case.name
            );
            assert_eq!(
                result.homo_index, case.homo_index,
                "{}: HOMO index",
                case.name
            );
            assert_eq!(
                result.lumo_index, case.lumo_index,
                "{}: LUMO index",
                case.name
            );

            let e_dev = max_abs_diff(&result.energies, &case.energies_ev);
            if e_dev > worst_energy.0 {
                worst_energy = (e_dev, case.name.clone());
            }
            let homo_dev = (result.homo_energy - case.homo_ev).abs();
            if homo_dev > worst_homo.0 {
                worst_homo = (homo_dev, case.name.clone());
            }
            let lumo_dev = (result.lumo_energy - case.lumo_ev).abs();
            if lumo_dev > worst_lumo.0 {
                worst_lumo = (lumo_dev, case.name.clone());
            }
            let gap_dev = (result.gap - case.gap_ev).abs();
            if gap_dev > worst_gap.0 {
                worst_gap = (gap_dev, case.name.clone());
            }

            // --- diagnostic: how far the STO-nG contraction is from being
            //     normalised (sci-form forces S_ii = 1) and how much that
            //     convention moves the eigenvalues.
            let diag_dev = case
                .overlap_true_diagonal
                .iter()
                .map(|v| (v - 1.0).abs())
                .fold(0.0f64, f64::max);
            if diag_dev > worst_diag.0 {
                worst_diag = (diag_dev, case.name.clone());
            }
            let diag_effect = max_abs_diff(&case.energies_ev, &case.energies_ev_true_diagonal);
            if diag_effect > worst_diag_effect.0 {
                worst_diag_effect = (diag_effect, case.name.clone());
            }
        }

        println!(
            "F86-EHT vs the numpy oracle: max|dS| = {:.3e} ({}), max|dH| = {:.3e} eV ({}), \
             max|dE| = {:.3e} eV ({}); max|dHOMO| = {:.3e} eV ({}), max|dLUMO| = {:.3e} eV ({}), \
             max|dgap| = {:.3e} eV ({}); S_ii normalisation error <= {:.3e} ({}), its effect on \
             the eigenvalues <= {:.3e} eV ({})",
            worst_overlap.0,
            worst_overlap.1,
            worst_h.0,
            worst_h.1,
            worst_energy.0,
            worst_energy.1,
            worst_homo.0,
            worst_homo.1,
            worst_lumo.0,
            worst_lumo.1,
            worst_gap.0,
            worst_gap.1,
            worst_diag.0,
            worst_diag.1,
            worst_diag_effect.0,
            worst_diag_effect.1,
        );

        assert!(
            worst_overlap.0 <= OVERLAP_TOL,
            "the EHT overlap matrix deviates from the numpy oracle by {:.3e} for {}",
            worst_overlap.0,
            worst_overlap.1
        );
        assert!(
            worst_h.0 <= H_TOL,
            "the EHT Hamiltonian deviates from the numpy oracle by {:.3e} eV for {}",
            worst_h.0,
            worst_h.1
        );
        assert!(
            worst_energy.0 <= ENERGY_TOL,
            "the EHT orbital energies deviate from the numpy oracle by {:.3e} eV for {}",
            worst_energy.0,
            worst_energy.1
        );
        assert!(
            worst_homo.0 <= ENERGY_TOL,
            "the EHT HOMO energy deviates from the numpy oracle by {:.3e} eV for {}",
            worst_homo.0,
            worst_homo.1
        );
        assert!(
            worst_lumo.0 <= ENERGY_TOL,
            "the EHT LUMO energy deviates from the numpy oracle by {:.3e} eV for {}",
            worst_lumo.0,
            worst_lumo.1
        );
        assert!(
            worst_gap.0 <= ENERGY_TOL,
            "the EHT HOMO-LUMO gap deviates from the numpy oracle by {:.3e} eV for {}",
            worst_gap.0,
            worst_gap.1
        );

        record(
            "F86-EHT",
            "eht_overlap_max_abs",
            "max_abs",
            worst_overlap.0,
            OVERLAP_TOL,
            worst_overlap.0 <= OVERLAP_TOL,
            fixture.cases.len(),
        );
        record(
            "F86-EHT",
            "eht_hamiltonian_max_abs_ev",
            "max_abs",
            worst_h.0,
            H_TOL,
            worst_h.0 <= H_TOL,
            fixture.cases.len(),
        );
        record(
            "F86-EHT",
            "eht_orbital_energy_max_abs_ev",
            "max_abs",
            worst_energy.0,
            ENERGY_TOL,
            worst_energy.0 <= ENERGY_TOL,
            fixture.cases.len(),
        );
        record(
            "F86-EHT",
            "eht_homo_max_abs_ev",
            "max_abs",
            worst_homo.0,
            ENERGY_TOL,
            worst_homo.0 <= ENERGY_TOL,
            fixture.cases.len(),
        );
        record(
            "F86-EHT",
            "eht_lumo_max_abs_ev",
            "max_abs",
            worst_lumo.0,
            ENERGY_TOL,
            worst_lumo.0 <= ENERGY_TOL,
            fixture.cases.len(),
        );
        record(
            "F86-EHT",
            "eht_gap_max_abs_ev",
            "max_abs",
            worst_gap.0,
            ENERGY_TOL,
            worst_gap.0 <= ENERGY_TOL,
            fixture.cases.len(),
        );
        record(
            "F86-EHT",
            "eht_overlap_diagonal_normalisation_error",
            "max_abs",
            worst_diag.0,
            0.4,
            true,
            fixture.cases.len(),
        );
        record(
            "F86-EHT",
            "eht_overlap_diagonal_convention_effect_ev",
            "max_abs",
            worst_diag_effect.0,
            1.0,
            true,
            fixture.cases.len(),
        );
    }

    #[test]
    fn f86_eht_derived_metal_params_match_oracle() {
        let fixture: Fixture = load("eht_parity.json");
        assert!(!fixture.derived_params.is_empty());

        let mut worst_vsip = (0.0f64, String::new());
        let mut worst_zeta = (0.0f64, String::new());

        for case in &fixture.derived_params {
            let ours = derived_params(case.z)
                .unwrap_or_else(|| panic!("Z={}: sci-form has no derived EHT parameters", case.z));
            assert_eq!(
                ours.orbitals.len(),
                case.orbitals.len(),
                "Z={}: derived shell count",
                case.z
            );
            for (got, want) in ours.orbitals.iter().zip(case.orbitals.iter()) {
                assert_eq!(got.n, want.n, "Z={}: principal quantum number", case.z);
                assert_eq!(got.l, want.l, "Z={}: angular momentum", case.z);
                assert_eq!(got.label, want.label, "Z={}: shell label", case.z);
                let v = (got.vsip - want.vsip).abs();
                if v > worst_vsip.0 {
                    worst_vsip = (v, format!("Z={} {}", case.z, want.label));
                }
                let z = (got.zeta - want.zeta).abs();
                if z > worst_zeta.0 {
                    worst_zeta = (z, format!("Z={} {}", case.z, want.label));
                }
            }
        }

        println!(
            "F86-EHT derived (hydrogenic) metal parameters: max|dVSIP| = {:.3e} eV ({}), \
             max|dzeta| = {:.3e} bohr^-1 ({}) over {} elements",
            worst_vsip.0,
            worst_vsip.1,
            worst_zeta.0,
            worst_zeta.1,
            fixture.derived_params.len()
        );

        assert!(
            worst_vsip.0 <= PARAM_TOL,
            "the derived VSIP deviates from the oracle by {:.3e} eV for {}",
            worst_vsip.0,
            worst_vsip.1
        );
        assert!(
            worst_zeta.0 <= PARAM_TOL,
            "the derived Slater exponent deviates from the oracle by {:.3e} for {}",
            worst_zeta.0,
            worst_zeta.1
        );

        record(
            "F86-EHT",
            "eht_derived_vsip_max_abs_ev",
            "max_abs",
            worst_vsip.0,
            PARAM_TOL,
            worst_vsip.0 <= PARAM_TOL,
            fixture.derived_params.len(),
        );
        record(
            "F86-EHT",
            "eht_derived_zeta_max_abs",
            "max_abs",
            worst_zeta.0,
            PARAM_TOL,
            worst_zeta.0 <= PARAM_TOL,
            fixture.derived_params.len(),
        );
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// F87-EEQ2019 — EEQ2019 partial charges vs an independent numpy implementation
// ═══════════════════════════════════════════════════════════════════════════

mod f87_eeq2019 {
    use super::*;
    use sci_form::charges_eeq::compute_eeq2019_charges;

    #[derive(Deserialize)]
    struct Case {
        name: String,
        elements: Vec<u8>,
        coords: Vec<f64>,
        total_charge: f64,
        charges: Vec<f64>,
        /// Coordination numbers of the oracle. sci-form does not expose them
        /// through the public API, so they are only used as a sanity check.
        coordination_numbers: Vec<f64>,
        charge_sum: f64,
    }

    #[derive(Deserialize)]
    struct Fixture {
        cases: Vec<Case>,
    }

    /// Tolerance (measured 2026-10-21).
    ///
    /// sci-form evaluates the error function with the Abramowitz & Stegun
    /// 7.1.26 rational approximation (absolute error <= 1.5e-7) while the
    /// oracle uses the exact `scipy.special.erf`; the difference propagates
    /// into the CN, the electronegativity and the Coulomb matrix, so the
    /// charges agree to ~1e-6 e.
    const CHARGE_TOL: f64 = 1e-5;
    /// The total charge is enforced exactly by the Lagrange constraint.
    const TOTAL_TOL: f64 = 1e-9;

    #[test]
    fn f87_eeq2019_charges_match_independent_oracle() {
        let fixture: Fixture = load("eeq2019_charges.json");
        assert!(
            fixture.cases.len() >= 8,
            "expected at least 8 EEQ2019 cases"
        );
        assert!(
            fixture.cases.iter().any(|c| c.total_charge.abs() > 0.5),
            "the fixture must contain a charged system to exercise the total-charge constraint"
        );

        let mut worst_charge = (0.0f64, String::new());
        let mut worst_total = (0.0f64, String::new());

        for case in &fixture.cases {
            let positions_bohr: Vec<[f64; 3]> = case
                .coords
                .chunks_exact(3)
                .map(|c| {
                    [
                        c[0] * 1.8897259886,
                        c[1] * 1.8897259886,
                        c[2] * 1.8897259886,
                    ]
                })
                .collect();

            let charges =
                compute_eeq2019_charges(&case.elements, &positions_bohr, case.total_charge)
                    .unwrap_or_else(|| panic!("{}: EEQ2019 charges unavailable", case.name));
            assert_eq!(
                charges.len(),
                case.charges.len(),
                "{}: charge count",
                case.name
            );

            // sanity check of the oracle's coordination numbers (they are not
            // exposed by sci-form's public API)
            assert!(
                case.coordination_numbers
                    .iter()
                    .all(|cn| cn.is_finite() && *cn >= 0.0),
                "{}: invalid coordination numbers in the fixture",
                case.name
            );

            let mut dev = 0.0f64;
            for (got, want) in charges.iter().zip(case.charges.iter()) {
                dev = dev.max((got - want).abs());
            }
            if dev > worst_charge.0 {
                worst_charge = (dev, case.name.clone());
            }

            let sum: f64 = charges.iter().sum();
            let total_dev = (sum - case.total_charge).abs();
            if total_dev > worst_total.0 {
                worst_total = (total_dev, case.name.clone());
            }
            assert!(
                (sum - case.charge_sum).abs() <= TOTAL_TOL,
                "{}: charge sum {} != reference {}",
                case.name,
                sum,
                case.charge_sum
            );
        }

        println!(
            "F87-EEQ2019 vs the numpy oracle: max|dq| = {:.3e} e ({}); \
             max|sum(q) - Q| = {:.3e} e ({}) over {} systems",
            worst_charge.0,
            worst_charge.1,
            worst_total.0,
            worst_total.1,
            fixture.cases.len()
        );

        assert!(
            worst_charge.0 <= CHARGE_TOL,
            "the EEQ2019 charges deviate from the numpy oracle by {:.3e} e for {}",
            worst_charge.0,
            worst_charge.1
        );
        assert!(
            worst_total.0 <= TOTAL_TOL,
            "the EEQ2019 total charge is violated by {:.3e} e for {}",
            worst_total.0,
            worst_total.1
        );

        record(
            "F87-EEQ2019",
            "eeq2019_charge_max_abs",
            "max_abs",
            worst_charge.0,
            CHARGE_TOL,
            worst_charge.0 <= CHARGE_TOL,
            fixture.cases.len(),
        );
        record(
            "F87-EEQ2019",
            "eeq2019_total_charge_max_abs",
            "max_abs",
            worst_total.0,
            TOTAL_TOL,
            worst_total.0 <= TOTAL_TOL,
            fixture.cases.len(),
        );
    }
}
